const binaryData = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64 = binaryData.toString('base64');
const mimeType = $input.item.binary.data.mimeType;

return [{
  json: {
    ...$input.item.json,
    imageBase64: base64,
    imageMimeType: mimeType
  }
}];

// ============================================================
// FILTRAR DATOS — con manejo defensivo de la respuesta de Groq
// Si el parseo falla o falta estructura, NO corta el flujo:
// devuelve { error:true, legible:false, motivo_error } para
// enrutar a un mensaje de "no pude leer el comprobante".
// ============================================================
const base = {
  phone: $input.item.json.phone,
  guia: $input.item.json.guia,
  transportista: $input.item.json.transportista,
};

function fallo(motivo) {
  return [{ json: { ...base, error: true, legible: false, motivo_error: motivo } }];
}

let content;
try {
  content = $input.item.json.choices[0].message.content;
} catch (e) {
  return fallo('Respuesta de IA sin contenido (choices vacío)');
}
if (!content) return fallo('Respuesta de IA vacía');

const clean = String(content).replace(/```json|```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(clean);
} catch (e) {
  return fallo('La IA no devolvió un JSON válido');
}

// acceso seguro: .valor solo si el campo existe
const v = (campo) => (parsed && parsed[campo] && typeof parsed[campo] === 'object')
  ? parsed[campo].valor : (parsed ? parsed[campo] : undefined);
const c = (campo) => (parsed && parsed[campo] && typeof parsed[campo] === 'object')
  ? parsed[campo].confianza : undefined;

// validación mínima: sin monto ni referencia no sirve
if (v('monto') === undefined && v('referencia') === undefined) {
  return fallo('La IA no extrajo monto ni referencia del comprobante');
}

return [{
  json: {
    ...base,
    error: false,
    monto: v('monto'),
    monto_confianza: c('monto'),
    tipo_pago: v('tipo_pago'),
    tipo_pago_confianza: c('tipo_pago'),
    referencia: v('referencia'),
    referencia_confianza: c('referencia'),
    fecha: v('fecha'),
    fecha_confianza: c('fecha'),
    hora: v('hora'),

    banco_billetera: v('banco_billetera'),
    banco_origen: v('banco_origen'),
    cuenta_destino: v('cuenta_destino'),
    cuenta_origen: v('cuenta_origen'),
    nombre_depositante: v('nombre_depositante'),
    nombre_beneficiario: v('nombre_beneficiario'),
    agencia: v('agencia'),

    legible: (parsed.legible !== undefined) ? parsed.legible : true
  }
}];

const data = $input.item.json;
let errores = [];
let warnings = [];
let fechaFutura = false;

// ─── CONFIGURACIÓN (desde $vars, con fallback a valores por defecto) ───
// Editar en n8n: Settings → Variables
//   NOMBRES_AJE  = lista separada por comas (ej: AJE,INDUSTRIAS AJE,AJE BOLIVIA)
//   CUENTAS_AJE  = lista separada por comas (ej: 7015046986392,1041309287,1311415157)
const _toList = (val) => (val ? String(val).split(',').map(s => s.trim()).filter(Boolean) : []);

const NOMBRES_AJE = _toList($vars.NOMBRES_AJE).length
  ? _toList($vars.NOMBRES_AJE)
  : ['AJE', 'INDUSTRIAS AJE', 'INDUSTRIAS AJE BOLIVIA', 'AJE BOLIVIA', 'AJE GROUP', 'AJEBOLIVIA', 'INDUSTRIAS AJEBOLIVIA'];

const CUENTAS_AJE = _toList($vars.CUENTAS_AJE).length
  ? _toList($vars.CUENTAS_AJE)
  : ['7015046986392', '1041309287', '1311415157'];

// ─── HELPERS ─────────────────────────────────────────────────
function normalizarTexto(texto) {
  if (!texto) return '';

  return texto.toString()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')      // quitar tildes
    .toUpperCase()
    .replace(/\bS\.?A\.?\b/g, '')         // quitar SA / S.A.
    .replace(/\bS\.?R\.?L\.?\b/g, '')     // quitar SRL
    .replace(/[^A-Z0-9]/g, '')            // quitar espacios y símbolos
    .trim();
}

function normalizarCuenta(cuenta) {
  if (!cuenta) return '';
  return cuenta.toString().replace(/[\*xX\s\-]/g, '');
}

function cuentaCoincide(cuentaDetectada, cuentasValidas) {
  const detectada = normalizarCuenta(cuentaDetectada);
  if (!detectada || detectada.length < 4) return false;

  // Limpiar prefijos de texto comunes antes de validar
  const soloDigitos = detectada.replace(/[^0-9xX\*]/gi, '');

  return cuentasValidas.some(valida => {
    const digitosValidos = normalizarCuenta(valida).replace(/[^0-9]/g, '');
    const partes = soloDigitos.split(/[^0-9]+/).filter(p => p.length > 0);
    return partes.every(parte => digitosValidos.includes(parte));
  });
}

function esBeneficiarioAJE(nombre) {
  const n = normalizarTexto(nombre);
  return NOMBRES_AJE.some(aje => n.includes(normalizarTexto(aje)));
}

// ─── MONTO ───────────────────────────────────────────────────
if (!data.monto || data.monto <= 0 || data.monto > 100000) {
  errores.push("Monto inválido");
}

// ─── FECHA ───────────────────────────────────────────────────
if (!data.fecha || !/^\d{4}-\d{2}-\d{2}$/.test(data.fecha)) {
  errores.push("Formato de fecha inválido");
} else {
  const fecha = new Date(data.fecha);
  const hoy = new Date();

  const inicioMesActual = new Date(hoy.getFullYear(), hoy.getMonth(), 1);
  if (fecha < inicioMesActual) {
    errores.push("Comprobante del mes pasado o anterior: " + data.fecha);
    fechaFutura = false;
  }

  if (fecha > hoy) {
    errores.push("Fecha en el futuro: " + data.fecha);
    fechaFutura = true;
  }

  const hace1anio = new Date();
  hace1anio.setFullYear(hace1anio.getFullYear() - 1);
  if (fecha < hace1anio) {
    warnings.push("Fecha muy antigua");
  }
}

// ─── REFERENCIA ──────────────────────────────────────────────
// Aseguramos que la referencia sea numérica y no un nombre
if (!data.referencia) {
  errores.push("Referencia inválida");
} else {
  const refStr = data.referencia.toString().trim();
  const soloLetras = /^[a-zA-ZáéíóúÁÉÍÓÚñÑ\s\.]+$/.test(refStr);
  if (soloLetras) {
    errores.push("Referencia inválida: parece un nombre, no un código numérico");
  } else if (refStr.replace(/[^0-9]/g, '').length < 4) {
    errores.push("Referencia inválida: muy pocos dígitos");
  }
}

// ─── CONFIANZA ───────────────────────────────────────────────
const confEstricta = 1;
const confMin = 0.8;

if (data.monto_confianza < confEstricta) {
  errores.push("Algunos datos no se leen bien");
}
if (data.referencia_confianza < confMin) {
  errores.push("Referencia poco confiable");
}
if (data.fecha_confianza < confMin) {
  warnings.push("Fecha poco confiable");
}

// ─── CAMPOS CLAVE ────────────────────────────────────────────
if (!data.monto || !data.referencia || !data.fecha) {
  errores.push("Faltan campos obligatorios");
}

// ─── HORA ────────────────────────────────────────────────────
// Muchos comprobantes (BNB, Mercantil, algunos tickets ATM) NO muestran hora.
// Ausencia de hora => revisión manual (warning), NO rechazo directo.
// Hora presente pero mal formada => error real (rechazo), como antes.
if (!data.hora) {
  warnings.push("Comprobante sin hora visible: enviar a revisión manual");
} else if (!/^\d{2}:\d{2}(:\d{2})?$/.test(data.hora)) {
  errores.push("Formato de hora inválido");
} else {
  const partes = data.hora.split(":").map(Number);
  const hh = partes[0];
  const mm = partes[1];
  const ss = partes[2] || 0;

  if (hh > 23 || mm > 59 || ss > 59) {
    errores.push("Hora inválida");
  }

  if (!fechaFutura && data.fecha) {
    const horaCompleta = `${hh.toString().padStart(2, '0')}:${mm.toString().padStart(2, '0')}:${ss.toString().padStart(2, '0')}`;
    const fechaHora = new Date(`${data.fecha}T${horaCompleta}`);
    const ahora = new Date();
    if (fechaHora > ahora) {
      errores.push("Fecha y hora en el futuro");
    }
  }
}

// ─── BENEFICIARIO AJE (OBLIGATORIO) ──────────────────────────
const beneficiario = data.nombre_beneficiario;

if (!beneficiario) {
  errores.push("No se detectó destinatario del pago");
} else if (!esBeneficiarioAJE(beneficiario)) {
  errores.push("El destinatario no corresponde a Industrias AJE: " + beneficiario);
}

// ─── BANCO_BILLETERA: no debe ser un nombre AJE ──────────────
// Fix: el modelo a veces pone el beneficiario como banco
if (data.banco_billetera && esBeneficiarioAJE(data.banco_billetera)) {
  warnings.push("banco_billetera detectado como nombre AJE (posible error de extracción)");
  // No bloqueamos, solo advertimos; la cuenta destino ya valida
}

// ─── VALIDACIÓN CUENTA DESTINO ───────────────────────────────
const cuentaDestino = data.cuenta_destino;

if (!cuentaDestino) {
  warnings.push("No se detectó número de cuenta destino");
} else if (!cuentaCoincide(cuentaDestino, CUENTAS_AJE)) {
  warnings.push("Número de cuenta destino no corresponde a AJE: " + cuentaDestino);
}

// ─── SCORE GLOBAL ────────────────────────────────────────────
const score = (
  data.monto_confianza +
  data.referencia_confianza +
  data.fecha_confianza
) / 3;

// ─── DECISIÓN FINAL ──────────────────────────────────────────
let estado = "aprobado";
if (errores.length > 0) {
  estado = "rechazado";
} else if (warnings.length > 0 || score < 0.75) {
  estado = "revision";
}

// ─── CATEGORIZACIÓN DE RECHAZO (aditivo) ─────────────────────
// Distingue rechazo por REGLA de negocio (reintentar foto no ayuda)
// de rechazo por CALIDAD/lectura (una nueva foto sí puede resolver).
const erroresDeRegla = [
  "El destinatario no corresponde",
  "Comprobante del mes pasado",
  "Fecha en el futuro",
  "Fecha y hora en el futuro",
  "Referencia inválida: parece un nombre",
  "No se detectó destinatario del pago"
];
const esRegla = errores.some(e => erroresDeRegla.some(r => e.includes(r)));
const categoria_rechazo = errores.length === 0
  ? null
  : (esRegla ? "regla" : "calidad");

return [{
  json: {
    ...data,
    score_global: score,
    estado,
    errores,
    warnings,
    categoria_rechazo
  }
}];

// ================================================
// NODO 2 - Extraer datos (Soporte doble formato)
// ================================================
const raw = $input.first().json;

const body = raw.body || raw;

const entry = body?.entry?.[0];
const changes = entry?.changes?.[0];
const valueMeta = changes?.value;

const valueDirect = body;
const value = valueMeta || valueDirect;

const messages = value?.messages || value?.mensajes;
const message = messages?.[0];

const contacts = value?.contacts || value?.contactos;
const contact = contacts?.[0];

if (!message) {
  return [{
    json: {
      debug: value,
      tipo: 'sin_mensaje',
      phone: null,
      continuar: false
    }
  }];
}

const messageId = message.id || message.identificador || null; // id único WA (idempotencia futura)
const phone = message.from || message.de;
const messageType = message.type || message.tipo;
const timestamp = new Date().toISOString();
const transportista = contact?.profile?.name || contact?.perfil?.nombre || 'Sin nombre';

let resultado = {
  messageId,
  phone,
  messageType,
  timestamp,
  transportista,
  continuar: true,
  texto: null,
  esFin: false,
  imageId: null,
  imageMimeType: null,
  buttonId: null,
  guiaCierre: null,// 👈 agregamos el campo
};

// TEXTO
if (messageType === 'text' || messageType === 'texto') {
  const textoRaw = (message.text?.body || message.texto?.cuerpo || "").trim();
  resultado.texto = textoRaw;
  const comandosCierre = ['FIN', 'CERRAR', 'LISTO', 'TERMINAR'];
  resultado.esFin = comandosCierre.includes(textoRaw.toUpperCase());
}

// IMAGEN
if (messageType === 'image' || messageType === 'imagen') {
  const imgData = message.image || message.imagen;
  resultado.imageId = imgData?.id || imgData?.identificación;
  resultado.imageMimeType = imgData?.mime_type || 'image/jpeg';
}
// INTERACTIVE (botones y listas)
if (messageType === 'interactive') {
  const interactive = message.interactive;
  let rawId = null;
  if (interactive?.type === 'button_reply') {
    rawId = interactive.button_reply.id;
  } else if (interactive?.type === 'list_reply') {
    rawId = interactive.list_reply.id;
  }
  if (rawId) {
    resultado.buttonId = rawId;

    // Extraer guía si viene en el buttonId
    if (rawId.startsWith('COMPLETAR_GUIA_')) {
      resultado.guiaCierre = rawId.replace('COMPLETAR_GUIA_', '');
    }
  }
}

return [{ json: resultado }];

const data = $input.item.json;

// 🔧 función reutilizable
function formatMoney(value) {
  if (value === null || value === undefined) return null;

  return Number(value).toLocaleString('es-BO', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
}

// 🔥 OUTPUT FORMATEADO
return [
  {
    json: {
      ...data,

      // 💰 montos formateados
      monto_fmt: formatMoney(data.monto),
      liquidacion_total_fmt: formatMoney(data.liquidacion_total),
      total_recaudado_fmt: formatMoney(data.total_recaudado),
      total_restante_fmt: formatMoney(data.total_restante)
    }
  }
];

const data = $input.item.json;

function formatMoney(value) {
  if (value === null || value === undefined) return null;
  return Number(value).toLocaleString('es-BO', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
}

return [
  {
    json: {
      ...data,
      monto_fmt: formatMoney($('confirma?').first().json.monto),
      liquidacion_total_fmt: formatMoney($('Buscamos la sesion').first().json.liquidacion_total),
      total_recaudado_fmt: formatMoney(data.total_recaudado),
      total_restante_fmt: formatMoney(data.total_restante)
    }
  }
];

