const binaryData = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64 = binaryData.toString('base64');
const mimeType = $input.item.binary.data.mimeType;

return [{
  json: {
    ...$input.item.json,
    imageBase64: base64,
    imageMimeType: mimeType
  }
}];

// ============================================================
// FILTRAR DATOS1 — con manejo defensivo de la respuesta de Groq
// Si el parseo falla o falta estructura, NO corta el flujo.
// ============================================================
const base = { phone: $input.item.json.phone };

function fallo(motivo) {
  return [{ json: { ...base, error: true, legible: false, codigo_encontrado: false, motivo_error: motivo } }];
}

let content;
try {
  content = $input.item.json.choices[0].message.content;
} catch (e) {
  return fallo('Respuesta de IA sin contenido (choices vacío)');
}
if (!content) return fallo('Respuesta de IA vacía');

const clean = String(content).replace(/```json|```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(clean);
} catch (e) {
  return fallo('La IA no devolvió un JSON válido');
}

const v = (campo) => (parsed && parsed[campo] && typeof parsed[campo] === 'object')
  ? parsed[campo].valor : (parsed ? parsed[campo] : undefined);
const c = (campo) => (parsed && parsed[campo] && typeof parsed[campo] === 'object')
  ? parsed[campo].confianza : undefined;

return [{
  json: {
    ...base,
    error: false,
    codigo_encontrado: parsed.codigo_encontrado,
    guia: v('codigo_completo'),
    numero: v('numero'),
    numero_confianza: c('numero'),
    codigo_confianza: c('codigo_completo'),
    legible: (parsed.legible !== undefined) ? parsed.legible : true
  }
}];

// --- Helpers multisucursal (variable n8n: SUCURSALES = COM:Santa Cruz|LP01:La Paz|CO01:Cochabamba) ---
const nombresSuc = {};
String($vars.SUCURSALES || 'COM:Santa Cruz').split('|').forEach(par => {
  const i = par.indexOf(':');
  const cod = (i >= 0 ? par.slice(0, i) : par).trim().toUpperCase();
  const nom = (i >= 0 ? par.slice(i + 1) : '').trim();
  if (cod) nombresSuc[cod] = nom || cod;
});
// Lista de prefijos válidos ordenada por longitud desc (para que LP01 no choque con LP, etc.)
const _prefijos = Object.keys(nombresSuc).sort((a,b) => b.length - a.length);
const _reCualquierPrefijo = new RegExp('(' + _prefijos.join('|') + ')-(\\d+)', 'i');

const fromImage = $input.first().json.guia;
const fromText = $('Mapeamos datos del mensaje').first().json.texto;

// Toma la guía de donde venga
const raw = (fromImage || fromText || "");

const match = String(raw).toUpperCase().match(_reCualquierPrefijo);

if (!match) {
  return [{
    json: {
      ...$input.first().json,
      guia_normalizada: null,
      sucursal_guia: null,
      sucursal_guia_nombre: null,
      error: 'No se encontró un código de guía válido (prefijos: ' + _prefijos.join(', ') + ')'
    }
  }];
}

const prefijo = match[1].toUpperCase();
const numero = match[2];
const numeroPadded = numero.padStart(16, '0');
const guiaNormalizada = `${prefijo}-${numeroPadded}`;

return [{
  json: {
    ...$input.first().json,
    guia_normalizada: guiaNormalizada,
    sucursal_guia: prefijo,
    sucursal_guia_nombre: nombresSuc[prefijo] || prefijo
  }
}];

// ============================================================
// Nodo: "Validar restante liq" — CON TOLERANCIA CORREGIDA
// ============================================================
// FIXES:
//   - redondeo solo aplica en el ÚLTIMO comprobante (cuando el monto
//     cubre el restante con diferencia dentro de tolerancia)
//   - comprobantes intermedios siempre tienen redondeo = 0
// ============================================================

const TOLERANCIA = Number($vars.TOLERANCIA_BS || 1.00);

const sesion      = $('Buscamos la sesion').first().json;
const comprobante = $('confirma?').first().json;

const restanteActual   = Number(sesion.total_restante);
const montoComprobante = Number(comprobante.monto);

const diferencia = montoComprobante - restanteActual; // positivo = pagó de más

// ── CASO 1: excede la tolerancia → BLOQUEAR ──────────────────
if (diferencia > TOLERANCIA) {
  return [{
    json: {
      ...comprobante,
      bloqueado: true,
      monto_efectivo: montoComprobante,
      redondeo: 0,
      motivo_bloqueo: `El monto ${montoComprobante} supera el restante ${restanteActual} (tolerancia: ${TOLERANCIA} Bs)`
    }
  }];
}

// ── CASO 2: dentro de tolerancia ─────────────────────────────
// monto_efectivo = lo que realmente se acredita a la sesión
const monto_efectivo = (diferencia > 0)
  ? restanteActual      // pagó de más → tope en el restante
  : montoComprobante;   // pagó de menos o exacto

// ── REDONDEO CORREGIDO ────────────────────────────────────────
// El redondeo solo existe cuando este comprobante CUBRE el restante
// con una diferencia mínima (centavos dentro de tolerancia).
//
// Es decir: solo cuando el nuevo restante queda en 0 o casi 0.
//
// nuevoRestante = restanteActual - monto_efectivo
const nuevoRestante = parseFloat((restanteActual - monto_efectivo).toFixed(2));

// Si el nuevo restante es menor a la tolerancia → es el pago final,
// el redondeo son los centavos que quedaron sin pagar.
// Si no → comprobante intermedio, redondeo = 0.
const esPagoFinal = nuevoRestante >= 0 && nuevoRestante < TOLERANCIA;
const redondeo    = esPagoFinal ? nuevoRestante : 0;

return [{
  json: {
    ...comprobante,
    bloqueado: false,
    monto_efectivo,
    redondeo   // ← 0 en pagos intermedios, centavos solo en el último pago
  }
}];

