// ============================================================
// PREPARAR RESUMEN WA - DETECCIÓN POR BUTTON ID
// ============================================================

const email = $('Buscar autorizado').first().json.email || 'el correo registrado';

// ── Sucursal del reporte (Sufijo o Router según la rama) ──
let sucNombre = '';
try { sucNombre = String($('Sufijo reporte COMP').first().json.reporte_nombre || ''); } catch (e) {}
if (!sucNombre) { try { sucNombre = String($('Sufijo reporte SES').first().json.reporte_nombre || ''); } catch (e) {} }
if (!sucNombre) { try { sucNombre = String($('Router reporte por fechas').first().json.reporte_nombre || ''); } catch (e) {} }
const lineaSuc = sucNombre ? `🏢 Sucursal: ${sucNombre}\n` : '';

// ── Detectar qué tipo de reporte se solicitó ────────────────
const buttonId = $('Mapeamos datos del mensaje').first().json.buttonId || '';
// Detección robusta del tipo (cubre botones viejos, nuevos REP_/RNG_ y rango escrito por contexto)
let _ctx = '';
try { _ctx = String($('Resolver Sucursal').first().json.rep_pendiente || ''); } catch(e) {}
const esSesiones =
  buttonId === 'INFORME_SESIONES' ||
  /^REP_SES_/.test(buttonId) ||
  /^RNG_SES_/.test(buttonId) ||
  /^PENDIENTE_RANGO\|SES\|/.test(_ctx);

// ── Obtener datos según la rama ─────────────────────────────
let resumen = {};

if (esSesiones) {
  // ── REPORTE DE SESIONES ──────────────────────────────────
  let itemsSesiones = [];
  try {
    itemsSesiones = $('Transformar para reporte1')
      .all()
      .map(i => i.json)
      .filter(i => !i._sin_datos && i.Estado !== undefined);
  } catch (e) {
    itemsSesiones = [];
  }

  if (itemsSesiones.length === 0) {
    resumen = {
      tipo: 'VACIO',
      email,
      mensaje_wa: '⚠️ No se encontraron sesiones para generar el reporte.'
    };
  } else {
    const sesionesActivas = itemsSesiones.filter(
      i => String(i.Estado || '').toUpperCase() === 'ACTIVO'
    ).length;

    const sesionesCompletadas = itemsSesiones.filter(
      i => String(i.Estado || '').toUpperCase() === 'COMPLETADO'
    ).length;

    resumen = {
      tipo: 'SESIONES',
      total_sesiones: itemsSesiones.length,
      activas: sesionesActivas,
      completadas: sesionesCompletadas,
      email,
      mensaje_wa:
        `🚚 *Reporte de Sesiones*\n` + lineaSuc + `\n` +
        `📈 Total de sesiones: ${itemsSesiones.length}\n` +
        `🟢 Activas: ${sesionesActivas}\n` +
        `✅ Completadas: ${sesionesCompletadas}\n\n` +
        `📧 El detalle completo se envió a: ${email}`
    };
  }

} else {
  // ── REPORTE DE COMPROBANTES / LIQUIDACIONES ──────────────
  let itemsComprobantes = [];
  try {
    itemsComprobantes = $('Transformar para reporte')
      .all()
      .map(i => i.json)
      .filter(i => !i._sin_datos && i.Deposito !== undefined);
  } catch (e) {
    itemsComprobantes = [];
  }

  if (itemsComprobantes.length === 0) {
    resumen = {
      tipo: 'VACIO',
      email,
      mensaje_wa: '⚠️ No se encontraron comprobantes para generar el reporte.'
    };
  } else {
    const guiasUnicas = new Set(
      itemsComprobantes.map(i => i.Guia).filter(Boolean)
    );

    const totalDepositos = itemsComprobantes.reduce(
      (sum, i) => sum + (Number(i.Deposito) || 0),
      0
    );

    const totalFmt = totalDepositos.toLocaleString('es-BO', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    });

    resumen = {
      tipo: 'COMPROBANTES',
      guias: guiasUnicas.size,
      comprobantes: itemsComprobantes.length,
      total_fmt: totalFmt,
      email,
      mensaje_wa:
        `📊 *Reporte de Liquidaciones*\n` + lineaSuc + `\n` +
        `✅ Guías: ${guiasUnicas.size}\n` +
        `✅ Comprobantes: ${itemsComprobantes.length}\n` +
        `💰 Total: Bs. ${totalFmt}\n\n` +
        `📧 El detalle completo se envió a: ${email}`
    };
  }
}

return [{ json: resumen }];

// ============================================================
// INFORME ACTUAL: Sesiones + Liquidaciones (multisucursal)
// - ADMIN: sucursal elegida en el menú o TODAS
//     · TODAS -> emite UN MENSAJE POR SUCURSAL + un mensaje de TOTALES
//       (evita superar el límite de longitud de WhatsApp)
//     · una sola sucursal -> un mensaje
// - CAJERO: su propia sucursal (con link a su maestro)
// - OPERATIVO: su propia sucursal (sin link)
//
// FUENTE DE VERDAD PARA "HOY": columna FE de los maestros (Detalle),
// con fill-down porque es una celda combinada (solo la primera fila
// de cada bloque trae el valor, el resto llega vacio).
// - mapLiq (guias del dia) se filtra por esa fecha.
// - sesiones tambien se filtran por esa fecha (no se elimina el filtro).
// ============================================================
const auth = $('Resolver Sucursal').first().json;
const tipoUser = String(auth.tipo || '').toUpperCase();

// --- Nombres de sucursal desde $vars.SUCURSALES (CODIGO:NOMBRE) ---
const nombresSuc = {};
String($vars.SUCURSALES || 'COM:Santa Cruz').split('|').forEach(par => {
  const i = par.indexOf(':');
  const cod = (i >= 0 ? par.slice(0, i) : par).trim().toUpperCase();
  const nom = (i >= 0 ? par.slice(i + 1) : '').trim();
  if (cod) nombresSuc[cod] = nom || cod;
});
const prefijosSuc = Object.keys(nombresSuc).sort((a, b) => b.length - a.length);
const reSucGuia = new RegExp('^(' + prefijosSuc.join('|') + ')-');
const sucDeGuia = g => { const m = String(g || '').toUpperCase().match(reSucGuia); return m ? m[1] : 'COM'; };

// --- Sucursal del informe: seleccion del ADMIN o sucursal propia ---
let sucInforme = String(auth.sucursal_codigo || 'COM').toUpperCase();
try {
  const s = String($('Sufijo reporte INF').first().json.reporte_sucursal || '');
  if (s) sucInforme = s.toUpperCase();
} catch (e) {}
const esTodas = (sucInforme === 'TODAS');

// --- Maestros usados (para links) ---
const maestroDe = c => (String(c).toUpperCase() === 'COM')
  ? $vars.SHEET_ID_MAESTRO
  : ($vars['MAESTRO_' + String(c).toUpperCase()] || $vars.SHEET_ID_MAESTRO);
let maestros = null;
try { maestros = $('Sufijo reporte INF').first().json.maestros; } catch (e) {}
if (!Array.isArray(maestros) || maestros.length === 0) {
  maestros = [{ codigo: sucInforme, nombre: nombresSuc[sucInforme] || sucInforme, id: auth.maestro_id || maestroDe(sucInforme) }];
}
const linkDe = cod => 'https://docs.google.com/spreadsheets/d/' + maestroDe(cod) + '/edit?usp=sharing';

// --- Helper: DD/MM/YYYY -> YYYY-MM-DD ---
function feAISO(d){ const m=String(d).match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  return m ? `${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}` : ''; }

// --- Fuente 2: Liquidaciones (1 o 3 maestros, fusionados) ---
// IMPORTANTE: usamos $input.all() (no $('Leer Liquidaciones (informe)').all())
// porque ese nodo se ejecuta una vez por sucursal dentro del loop, y referenciarlo
// por nombre solo devuelve los datos de su ULTIMA ejecucion. Este nodo recibe
// directamente la salida "done" del loop, que ya trae las filas de las 3
// sucursales acumuladas correctamente.
let _liqAll = $input.all();
const _filasMaestro = _liqAll.map(i => i.json);

// --- Fill-down de FE (celda combinada) + construir mapLiq y fechasDiaPorSuc ---
// El FE solo viene en la primera fila de cada bloque de sucursal; se
// propaga hacia abajo hasta encontrar un nuevo valor o el fin del bloque.
// IMPORTANTE: el set de fechas validas es POR SUCURSAL (no compartido),
// porque si el maestro de una sucursal tiene su FE desactualizado (ej.
// alguien olvido actualizar la celda A2), esa fecha vieja NO debe filtrar
// las sesiones de las OTRAS sucursales.
// NOTA: el header estandar de esta columna es 'FE'; se deja 'FECHA' como
// respaldo por si algun maestro todavia no fue renombrado.
const ultimaFEPorSuc = {};
const fechasDiaPorSuc = {}; // { COM: Set(iso), LP01: Set(iso), CO01: Set(iso) }
const mapLiq = {};
_filasMaestro.forEach(l => {
  const veh = (l['VEHICULO'] || '').toString().trim();
  const guia = (l['SER_IMPREG'] || '').toString().trim().toUpperCase();
  const sucRow = guia ? sucDeGuia(guia) : null;
  const feRaw = l.FE || l.FECHA;

  if (sucRow && feRaw && String(feRaw).trim() && String(feRaw).trim() !== 'Total general') {
    ultimaFEPorSuc[sucRow] = String(feRaw).trim();
  }

  // Saltar filas separadoras / "Total general" / sin guia
  if (!veh || !guia || !sucRow) return;

  const feISO = ultimaFEPorSuc[sucRow] ? feAISO(ultimaFEPorSuc[sucRow]) : '';
  if (feISO) {
    if (!fechasDiaPorSuc[sucRow]) fechasDiaPorSuc[sucRow] = new Set();
    fechasDiaPorSuc[sucRow].add(feISO);
  }

  const total = Number(l['Suma de IMPCOB']) || 0;
  if (total > 0) {
    // Si hay fecha, solo se guarda si corresponde al dia de ESA sucursal;
    // si no hay fecha detectable, se conserva para no perder datos.
    if (!feISO || fechasDiaPorSuc[sucRow].has(feISO)) {
      mapLiq[guia] = { total, vehiculo: veh };
    }
  }
});

// --- Fuente 1: Sesiones (centralizada) ---
let _ses; try { _ses = $('Leer sesiones (informe)').all(); } catch(e) { _ses = $('Leer sesiones').all(); }
let todasSesiones = _ses.map(i => i.json);
if (!esTodas) {
  todasSesiones = todasSesiones.filter(s => String(s.sucursal || 'COM').trim().toUpperCase() === sucInforme);
}

// Filtra sesiones ACTIVO/COMPLETADO usando SOLO las fechas validas de la
// sucursal correspondiente a cada sesion (nunca un set compartido).
function sesionesValidasDeHoy(lista) {
  return lista.filter(s => {
    if (s.estado !== 'ACTIVO' && s.estado !== 'COMPLETADO') return false;
    const cod = String(s.sucursal || sucDeGuia(s.guia)).toUpperCase();
    const validas = fechasDiaPorSuc[cod];
    if (!validas || validas.size === 0) return true; // sin fecha detectable: no se descarta
    return validas.has(String(s.s_fecha || '').substring(0,10));
  });
}

const sesiones = sesionesValidasDeHoy(todasSesiones);

if (sesiones.length === 0 && Object.keys(mapLiq).length === 0) {
  return [{ json: { resumen: '⚠️ *Sin datos disponibles para hoy.*' }, pairedItem: { item: 0 } }];
}

// --- Helpers ---
const fmt = v => Number(v).toLocaleString('es-BO', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const limpiarGuia = (g) => { const m = g.toUpperCase().match(/([A-Z0-9]+)-0*(\d+)/); return m ? `${m[1]}-${m[2]}` : g; };
const fecha = new Date().toLocaleDateString('es-BO', { day: '2-digit', month: '2-digit', year: 'numeric' });

// ============================================================
// Construye el bloque de informe para una sucursal (o TODAS)
// sucursalFiltro: codigo de sucursal ('COM','LP01','CO01') o 'TODAS'
// Devuelve { texto, esperado, recaudado }
// ============================================================
function construirBloque(sesionesSet, encabezado, sucursalFiltro) {
  const guiasConSesion = new Set(sesionesSet.map(s => (s.guia || '').toString().trim().toUpperCase()));

  // pendientes = guias del maestro (de HOY) sin sesion, filtradas por
  // sucursal directamente desde el prefijo de la guia (no depende de
  // que existan sesiones para esa sucursal).
  const pendientes = Object.entries(mapLiq)
    .filter(([guia]) => !guiasConSesion.has(guia))
    .filter(([guia]) => sucursalFiltro === 'TODAS' ? true : sucDeGuia(guia) === sucursalFiltro)
    .map(([guia, data]) => ({ guia, ...data }));

  const activas = sesionesSet.filter(s => s.estado === 'ACTIVO');
  const completadas = sesionesSet.filter(s => s.estado === 'COMPLETADO');

  let esperado = 0, recaudado = 0;
  function proc(s) {
    const g = (s.guia || '').toString().trim().toUpperCase();
    const liq = (mapLiq[g] && mapLiq[g].total) || Number(s.liquidacion_total) || 0;
    const rec = Number(s.total_recaudado) || 0;
    esperado += liq; recaudado += rec;
    const pct = liq > 0 ? Math.round((rec / liq) * 100) : 0;
    return `- *${limpiarGuia(g)}* (${s.transportista || 'S/N'})\n   └ ${fmt(rec)} / ${fmt(liq)} Bs (${pct}%)`;
  }

  let txt = encabezado;
  if (pendientes.length > 0) {
    txt += `\n⭕ *PENDIENTES (${pendientes.length})*\n`;
    txt += pendientes.map(p => { esperado += p.total; return `- *${limpiarGuia(p.guia)}* (${p.vehiculo})\n   └ Esperado: ${fmt(p.total)} Bs`; }).join('\n');
  }
  if (activas.length > 0) {
    txt += `\n\n🟡 *EN CURSO (${activas.length})*\n` + activas.map(proc).join('\n');
  }
  if (completadas.length > 0) {
    txt += `\n\n✅ *COMPLETADAS (${completadas.length})*\n` + completadas.map(proc).join('\n');
  }
  const restante = esperado - recaudado;
  const pctG = esperado > 0 ? Math.round((recaudado / esperado) * 100) : 0;
  txt += `\n\n━━━━━━━━━━━━━━\n📊 *TOTALES*\n` +
         `• Esperado: ${fmt(esperado)} Bs\n` +
         `• Recaudado: ${fmt(recaudado)} Bs (*${pctG}%*)\n` +
         `• Restante: ${fmt(restante)} Bs`;
  if ((pendientes.length + activas.length + completadas.length) > 0 && activas.length === 0 && pendientes.length === 0) {
    txt += `\n\n🎉 *¡Todo completado!*`;
  }
  return { texto: txt, esperado, recaudado };
}

const mensajes = [];

if (esTodas) {
  // --- UN MENSAJE POR SUCURSAL ---
  let totEsp = 0, totRec = 0;
  const codigos = maestros.map(m => m.codigo);
  codigos.forEach((cod, idx) => {
    const sesSuc = sesiones.filter(s => String(s.sucursal || sucDeGuia(s.guia)).toUpperCase() === cod);
    const enc = `📋 *Liquidaciones - ${fecha}*\n🏢 ${nombresSuc[cod] || cod}  (${idx+1}/${codigos.length})\n`;
    const b = construirBloque(sesSuc, enc, cod);
    totEsp += b.esperado; totRec += b.recaudado;
    let txt = b.texto;
    if (tipoUser === 'ADMIN' || tipoUser === 'CAJERO') {
      txt += `\n\n📂 Planilla: ${linkDe(cod)}`;
    }
    mensajes.push({ resumen: txt });
  });
  // --- MENSAJE FINAL DE TOTALES CONSOLIDADOS ---
  const restante = totEsp - totRec;
  const pctG = totEsp > 0 ? Math.round((totRec / totEsp) * 100) : 0;
  let txtTot = `📊 *RESUMEN GENERAL - ${fecha}*\n🌐 Todas las sucursales\n\n`;
  codigos.forEach(cod => {
    const sesSuc = sesiones.filter(s => String(s.sucursal || sucDeGuia(s.guia)).toUpperCase() === cod);
    const b = construirBloque(sesSuc, '', cod);
    const pct = b.esperado > 0 ? Math.round((b.recaudado / b.esperado) * 100) : 0;
    txtTot += `• *${nombresSuc[cod] || cod}*: ${fmt(b.recaudado)} / ${fmt(b.esperado)} Bs (${pct}%)\n`;
  });
  txtTot += `\n━━━━━━━━━━━━━━\n` +
            `• Esperado total: ${fmt(totEsp)} Bs\n` +
            `• Recaudado total: ${fmt(totRec)} Bs (*${pctG}%*)\n` +
            `• Restante total: ${fmt(restante)} Bs`;
  mensajes.push({ resumen: txtTot });

} else {
  // --- UNA SOLA SUCURSAL: un mensaje ---
  const enc = `📋 *Liquidaciones - ${fecha}*\n🏢 ${nombresSuc[sucInforme] || sucInforme}\n`;
  const b = construirBloque(sesiones, enc, sucInforme);
  let txt = b.texto;
  if (tipoUser === 'ADMIN' || tipoUser === 'CAJERO') {
    txt += `\n\n📂 Planilla: ${linkDe(sucInforme)}`;
  }
  mensajes.push({ resumen: txt });
}

return mensajes.map(m => ({ json: m, pairedItem: { item: 0 } }));

