const sesionActiva = $('Mapear montos').first().json;
const todasSesiones = $items(); // resultado de Buscar otras sesiones activas

function fmt(v) {
  return Number(v).toLocaleString('es-BO', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
}

// Sesiones pendientes (las que NO son la activa)
const otras = todasSesiones.filter(
  i => i.json.guia !== sesionActiva.guia
);

// Mensaje principal — sesión en foco
let msg =
  "👋 Como va tu dia, "+ $('Buscar autorizado').first().json.nombre + "?\n\n" +
  "📊 *Resumen de tu sesión activa*\n\n" +
  "📄 *Guía:* " + sesionActiva.guia + "\n" +
  "💰 *Total del viaje:* " + fmt(sesionActiva.liquidacion_total) + " Bs\n" +
  "📥 *Recaudado:* " + fmt(sesionActiva.total_recaudado) + " Bs\n" +
  "📉 *Restante:* " + fmt(sesionActiva.total_restante) + " Bs\n\n" +
  "🚚 Sigue así para completar tu viaje con éxito.";

// Aviso de otras sesiones
if (otras.length > 0) {
  msg += "\n\n⚠️ *Tienes " + otras.length + " sesión(es) pendiente(s):*\n";
  msg += otras.map(i =>
    "• " + i.json.guia +
    " — Restante: " + fmt(i.json.total_restante) + " Bs"
  ).join("\n");
  msg += "\n\n📌 Envía el código de guía para cambiar de sesión activa.";
}

return [{ json: { mensaje: msg, phone: sesionActiva.phone } }];

