// ============================================================
// TRANSFORMAR SESIONES → FORMATO REPORTE PARA EXCEL
// FIX IMPORTANTE:
//   Cuando el nodo anterior devuelve un item vacío ({}),
//   n8n sigue considerando que existe 1 registro.
//   Por ello debemos filtrar únicamente sesiones que
//   realmente tengan una guía válida.
// ============================================================

// ── Helper: convertir a string seguro (evita notación científica) ─────
function toSafeString(val) {
  if (val === null || val === undefined || val === '' || val === 'null') {
    return '';
  }

  const str = String(val).trim();

  if (/[eE]/.test(str) && !isNaN(Number(str))) {
    return BigInt(Math.round(Number(str))).toString();
  }

  if (!isNaN(Number(str)) && Number(str) > 999999999999) {
    return BigInt(Math.round(Number(str))).toString();
  }

  return str;
}

// ── Helper: formatear monto con 2 decimales ─────────────────
function formatearMonto(valor) {
  const num = Number(valor);
  if (isNaN(num)) return 0.00;
  return parseFloat(num.toFixed(2));
}

// ── Helper: extraer número de guía sin ceros a la izquierda ──
function extraerNumeroGuia(guia) {
  if (!guia) return '';
  const match = String(guia).toUpperCase().match(/([A-Z0-9]+)-0*(\\d+)/);
  return match ? match[2] : String(guia).trim();
}

// ── Helper: obtener número para ordenar ──────────────────────
function obtenerNumeroGuiaInt(guia) {
  const numero = extraerNumeroGuia(guia);
  const num = parseInt(numero, 10);
  return isNaN(num) ? 0 : num;
}

// ── Helper: fecha ISO → DD/MM/YYYY HH:mm:ss ──────────────────
function formatearFechaHora(fecha) {
  if (!fecha) return '';

  const d = new Date(fecha);
  if (isNaN(d.getTime())) return String(fecha);

  const pad = (n) => String(n).padStart(2, '0');

  return (
    [
      pad(d.getDate()),
      pad(d.getMonth() + 1),
      d.getFullYear()
    ].join('/') +
    ' ' +
    [
      pad(d.getHours()),
      pad(d.getMinutes()),
      pad(d.getSeconds())
    ].join(':')
  );
}

// ── Helper: fecha YYYY-MM-DD → DD/MM/YYYY ────────────────────
function formatearFecha(fecha) {
  if (!fecha) return '';

  const match = String(fecha).match(/^(\\d{4})-(\\d{2})-(\\d{2})$/);
  if (match) {
    return `${match[3]}/${match[2]}/${match[1]}`;
  }

  return String(fecha);
}

// ============================================================
// 1. Leer sesiones del input actual
// ============================================================
const sesionesRaw = $input.all().map(item => item.json);

// ============================================================
// 2. Filtrar únicamente registros válidos (con guía)
// ============================================================
const sesiones = sesionesRaw.filter(s =>
  s &&
  s.guia &&
  String(s.guia).trim() !== ''
);

// ============================================================
// 3. Caso vacío (igual que el flujo de comprobantes)
// ============================================================
if (sesiones.length === 0) {
  return [{
    json: {
      _sin_datos: true,
      resumen: 'No existen sesiones para generar el reporte.'
    }
  }];
}

// ============================================================
// 4. Transformar datos
// ============================================================
const filas = sesiones.map(sesion => {
  const numeroGuia = extraerNumeroGuia(sesion.guia);
  const numeroGuiaInt = obtenerNumeroGuiaInt(sesion.guia);

  return {
    _numeroGuiaInt: numeroGuiaInt,
    json: {
      Fecha: formatearFecha(sesion.s_fecha),
      Sucursal: sesion.sucursal || '',
      Guia: sesion.guia || '',
      Placa: sesion.transportista || '',
      Telefono: toSafeString(sesion.phone),

      Estado: sesion.estado || '',

      Liquidacion_Total: formatearMonto(sesion.liquidacion_total),
      Total_Recaudado: formatearMonto(sesion.total_recaudado),
      Total_Restante: formatearMonto(sesion.total_restante),

      Fecha_Inicio: formatearFechaHora(sesion.fecha_inicio),

      Motivo_Cierre: sesion.motivo_cierre || '',
    }
  };
});

// ============================================================
// 5. Caso vacío después de la transformación
// ============================================================
if (filas.length === 0) {
  return [{
    json: {
      _sin_datos: true,
      resumen: 'No existen sesiones para generar el reporte.'
    }
  }];
}

// ============================================================
// 6. Ordenar por número de guía
// ============================================================
filas.sort((a, b) => a._numeroGuiaInt - b._numeroGuiaInt);

// ============================================================
// 7. Retornar resultado final
// ============================================================
return filas.map(f => ({
  json: f.json
}));

