for (const item of $input.all()) {
  let rawValue = item.json.liquidacion_total;

  // 1. Si ya es un número, validamos que no sea NaN y lo dejamos pasar
  if (typeof rawValue === 'number') {
    item.json.liquidacion_total = isNaN(rawValue) ? 0 : rawValue;
    continue;
  }

  // 2. Si viene como texto (o cualquier otra cosa), lo limpiamos a fondo
  if (rawValue) {
    // Convertimos a string y quitamos espacios, letras o símbolos de moneda
    let cleanValue = String(rawValue).trim().replace(/[^\d.,-]/g, '');

    // Manejo inteligente de formatos (ej: 1.234,56 vs 1,234.56)
    if (cleanValue.includes(',') && cleanValue.includes('.')) {
      if (cleanValue.indexOf('.') < cleanValue.indexOf(',')) {
        // Formato Latino/Europeo: 1.234,56 -> quitamos puntos, cambiamos coma por punto
        cleanValue = cleanValue.replace(/\./g, '').replace(',', '.');
      } else {
        // Formato Americano: 1,234.56 -> quitamos comas
        cleanValue = cleanValue.replace(/,/g, '');
      }
    } else if (cleanValue.includes(',')) {
      // Si solo tiene coma, asumimos que es el decimal (ej: 1500,50 -> 1500.50)
      cleanValue = cleanValue.replace(',', '.');
    }

    const parsed = parseFloat(cleanValue);
    item.json.liquidacion_total = isNaN(parsed) ? 0 : parsed;
  } else {
    // Si viene null, undefined o vacío, lo dejamos en 0
    item.json.liquidacion_total = 0;
  }
}

return $input.all();

