// === Resolver Sucursal del usuario ===
// Lee el código de sucursal de la fila de 'autorizados' (columna 'sucursal').
// Variable n8n: SUCURSALES = COM:Santa Cruz|LP01:La Paz|CO01:Cochabamba (CODIGO:NOMBRE)
// Hojas operativas centralizadas (sesiones / comprobantes / comprobantes_rechazados
// con columna 'sucursal'). El maestro de liquidaciones es un archivo por sucursal:
//   COM  -> $vars.SHEET_ID_MAESTRO
//   XXXX -> $vars.MAESTRO_XXXX (ej. MAESTRO_LP01, MAESTRO_CO01)
// Mantiene intactos todos los campos que ya traía 'Buscar autorizado'.

const data = $input.item.json;

const nombresSuc = {};
String($vars.SUCURSALES || 'COM:Santa Cruz').split('|').forEach(par => {
  const i = par.indexOf(':');
  const cod = (i >= 0 ? par.slice(0, i) : par).trim().toUpperCase();
  const nom = (i >= 0 ? par.slice(i + 1) : '').trim();
  if (cod) nombresSuc[cod] = nom || cod;
});

const codigo = String(data.sucursal || 'COM').trim().toUpperCase();
const nombre = nombresSuc[codigo] || codigo;

const maestroDe = c => (String(c).toUpperCase() === 'COM')
  ? $vars.SHEET_ID_MAESTRO
  : ($vars['MAESTRO_' + String(c).toUpperCase()] || $vars.SHEET_ID_MAESTRO);
const maestroId = maestroDe(codigo);

return [{
  json: {
    ...data,
    sucursal_codigo: codigo,
    sucursal_nombre: nombre,
    maestro_id: maestroId,
    maestro_link: 'https://docs.google.com/spreadsheets/d/' + maestroId + '/edit?usp=sharing',
    sucursal_sufijo: '' // compatibilidad: hojas centralizadas, ya no hay sufijo de pestaña
  }
}];

// === Sanitizar respuesta del admin (LLM) para mensaje interactivo WA ===
// WhatsApp interactive usa JSON; comillas, saltos o backslashes crudos rompen el body.
// Emitimos:
//   texto_limpio  -> texto legible (por compatibilidad)
//   texto_wa      -> string YA escapado como literal JSON (sin las comillas externas)
//                    para insertarse directo en el body como: "text": {{ ...texto_wa }}

const out = $input.item.json.output;
let texto = '';
try {
  texto = (Array.isArray(out) ? out[0].texto : out.texto) || '';
} catch (e) {
  texto = '';
}

// 1) Forzar string y normalizar saltos de línea
texto = String(texto)
  .replace(/\r\n/g, '\n')
  .replace(/\r/g, '\n');

// 2) Quitar caracteres de control no imprimibles (excepto \n y \t)
texto = texto.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '');

// 3) WhatsApp interactive body: límite ~1024. Recortar con margen.
if (texto.length > 1000) texto = texto.slice(0, 997) + '...';

// 4) Respaldo si quedó vacío
if (!texto.trim()) {
  texto = 'Hola, ¿en qué puedo ayudarte? Puedes pedirme el Informe Actual, el Reporte por correo o un Cierre de Guía.';
}

// 5) Escapar como literal JSON. JSON.stringify produce un string CON comillas
//    externas y con \", \\, \n, etc. ya escapados de forma válida para WhatsApp.
//    El body lo inserta SIN comillas adicionales.
const textoJson = JSON.stringify(texto);

return [{
  json: {
    ...$input.item.json,
    texto_limpio: texto,   // legible
    texto_wa: textoJson    // literal JSON listo para el body (incluye comillas)
  }
}];

