const bid = String($('Mapeamos datos del mensaje').item.json.buttonId || '');
const auth = $('Resolver Sucursal').item.json;
const nombresSuc = {};
String($vars.SUCURSALES || 'COM:Santa Cruz').split('|').forEach(par => {
  const i = par.indexOf(':');
  const cod = (i >= 0 ? par.slice(0, i) : par).trim().toUpperCase();
  const nom = (i >= 0 ? par.slice(i + 1) : '').trim();
  if (cod) nombresSuc[cod] = nom || cod;
});

let suc = String(auth.sucursal_codigo || 'COM').toUpperCase();
const m = bid.match(/^REP_[A-Z0-9]+_([A-Z0-9]+)$/);
if (m) suc = m[1].toUpperCase();
const nombre = (suc === 'TODAS') ? 'Todas las sucursales' : (nombresSuc[suc] || suc);
return [{ json: { ...$input.item.json, reporte_sucursal: suc, reporte_nombre: nombre } }];

// === Resolver sucursal del reporte ===
// ADMIN: elige por botón/lista (REP_X_<SUC>, incluye TODAS).
