if (!sucRep) { try { sucRep = String($('Sufijo reporte COMP').item.json.reporte_sucursal || '').toUpperCase(); } catch(e) {} }
if (!sucRep) { try { sucRep = String($('Router reporte por fechas').item.json.reporte_sucursal || '').toUpperCase(); } catch(e) {} }
if (!sucRep) { try { sucRep = String($('Resolver Sucursal').item.json.sucursal_codigo || '').toUpperCase(); } catch(e) {} }
if (sucRep && sucRep !== 'TODAS') {
  res = res.filter(f => String(f.sucursal || 'COM').trim().toUpperCase() === sucRep);
}

return res.map(f=>({ json:{ ...f, _modo:modo, _desde:desde, _hasta:hasta, _suc_reporte:sucRep } }));

// === Filtrar filas por rango de fecha (DIA / RANGO / HISTORIAL) y por sucursal ===
const filas = $input.all().map(i => i.json);
const bid = String($('Mapeamos datos del mensaje').item.json.buttonId || '');
const texto = String($('Mapeamos datos del mensaje').item.json.texto || '');
let ctx=''; try { ctx = String($('Resolver Sucursal').item.json.rep_pendiente || ''); } catch(e){}

const fechasTxt = (texto.match(/\d{1,2}\/\d{1,2}\/\d{4}/g) || []);
// El contexto de rango SOLO vale si el mensaje actual es respuesta de fechas (sin botón + con fechas)
const esRespFechas = (!bid) && fechasTxt.length >= 1 && ctx.startsWith('PENDIENTE_RANGO');

let modo = 'DIA';
const mBid = bid.match(/^RNG_[A-Z0-9]+_[A-Z0-9]+_([A-Z]+)$/);
if (mBid) modo = mBid[1].toUpperCase();
else if (esRespFechas) modo = 'RANGO';

const hoy = $now.toFormat('yyyy-MM-dd');
function aISO(d){ const m=String(d).trim().match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/); if(!m) return null;
  return `${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`; }

let desde=null, hasta=null;
if (modo==='HISTORIAL'){ /* todo */ }
else if (modo==='RANGO'){
  desde = aISO(fechasTxt[0]); hasta = aISO(fechasTxt[1] || fechasTxt[0]);
  if(!desde||!hasta){ return [{ json:{ _error_fechas:true } }]; }
  if (desde > hasta){ const t=desde; desde=hasta; hasta=t; }
} else { desde=hoy; hasta=hoy; }

let res=filas;
if(desde&&hasta){
  res=filas.filter(f=>{ const sf=String(f.s_fecha||'').substring(0,10); return sf && sf>=desde && sf<=hasta; });
}

// --- Resolver sucursal del reporte de forma robusta ---
// Orden: 1) buttonId RNG_TIPO_SUC_MODO  2) contexto rango  3) nodo Sufijo  4) Router  5) sucursal propia
let sucRep = '';
const mSucBtn = bid.match(/^RNG_[A-Z0-9]+_([A-Z0-9]+)_[A-Z]+$/);
if (mSucBtn) sucRep = mSucBtn[1].toUpperCase();
if (!sucRep) { const mCtx = ctx.match(/^PENDIENTE_RANGO\|[A-Z0-9]+\|([A-Z0-9]+)$/); if (mCtx) sucRep = mCtx[1].toUpperCase(); }
if (!sucRep) { try { sucRep = String($('Sufijo reporte SES').item.json.reporte_sucursal || '').toUpperCase(); } catch(e) {} }
if (!sucRep) { try { sucRep = String($('Router reporte por fechas').item.json.reporte_sucursal || '').toUpperCase(); } catch(e) {} }
if (!sucRep) { try { sucRep = String($('Resolver Sucursal').item.json.sucursal_codigo || '').toUpperCase(); } catch(e) {} }
if (sucRep && sucRep !== 'TODAS') {
  res = res.filter(f => String(f.sucursal || 'COM').trim().toUpperCase() === sucRep);
}

return res.map(f=>({ json:{ ...f, _modo:modo, _desde:desde, _hasta:hasta, _suc_reporte:sucRep } }));

