// Guarda la selección del reporte para recuperarla cuando lleguen las fechas escritas.
const bid = String($('Mapeamos datos del mensaje').item.json.buttonId || '');
const auth = $('Resolver Sucursal').item.json;
// bid: RNG_<tipo>_<suc>_RANGO  -> guardamos "PENDIENTE_RANGO|<tipo>|<suc>"
const m = bid.match(/^RNG_([A-Z0-9]+)_([A-Z0-9]+)_RANGO$/);
const tipo = m ? m[1] : 'COMP';
const suc  = m ? m[2] : String(auth.sucursal_codigo || 'COM').toUpperCase();
return [{ json: { ...$input.item.json, _ctx_reporte: `PENDIENTE_RANGO|${tipo}|${suc}` } }];

