// Recupera la selección guardada (contexto: PENDIENTE_RANGO|tipo|suc) y prepara el reporte por rango.
const auth = $('Resolver Sucursal').item.json;
const ctx = String(auth.rep_pendiente || '');
const m = ctx.match(/^PENDIENTE_RANGO\|([A-Z0-9]+)\|([A-Z0-9]+)$/);
const tipo = m ? m[1] : 'COMP';
const suc  = (m ? m[2] : String(auth.sucursal_codigo || 'COM')).toUpperCase();
const nombresSuc = {};
String($vars.SUCURSALES || 'COM:Santa Cruz').split('|').forEach(par => {
  const i = par.indexOf(':');
  const cod = (i >= 0 ? par.slice(0, i) : par).trim().toUpperCase();
  const nom = (i >= 0 ? par.slice(i + 1) : '').trim();
  if (cod) nombresSuc[cod] = nom || cod;
});
const nombre = (suc === 'TODAS') ? 'Todas las sucursales' : (nombresSuc[suc] || suc);
return [{ json: { ...$input.item.json, reporte_sucursal: suc, reporte_nombre: nombre, _tipo_reporte: tipo, _modo_forzado: 'RANGO' } }];

// ============================================================
// ENSAMBLAR PROMPT — Opción 3 (híbrido)
//   ZONA A (fija) + reglas activas del Sheet agrupadas por campo + ZONA C (fija)
// Reenvía imageBase64 / imageMimeType desde "CONVERTIR A BASE64"
// para no perder la imagen al haber leído el Sheet en medio.
// ============================================================

const ZONA_A = `Eres un extractor de datos de comprobantes de pago bolivianos. Analiza esta imagen y extrae TODOS los datos disponibles en formato JSON sin explicaciones ni texto adicional.

Para cada campo devuelve un objeto con "valor" y "confianza".

━━━ REGLAS ESTRICTAS DE CONFIANZA ━━━
- 1.0 → perfectamente claro, nítido, sin ambigüedad visual.
- 0.8 → legible pero con ligera duda (borroso, pequeño o parcialmente visible).
- 0.5 → parcialmente legible o inferido.
- 0.2 → muy dudoso, incompleto o apenas visible.
- 0.0 → no se puede leer → valor: null.
- Si el valor fue inferido → confianza <= 0.5.
- Si hay desenfoque o corte → confianza <= 0.8.
- PROHIBIDO usar 1.0 si la imagen no es perfectamente clara.

AUTOVERIFICACIÓN:
Antes de asignar confianza, evalúa si el texto es claramente visible o lo estás deduciendo.

━━━ REGLAS DE EXTRACCIÓN POR CAMPO ━━━`;

const ZONA_C = `Devuelve SOLO el JSON con esta estructura:

{
  "monto": {"valor": (número decimal), "confianza": (0.0-1.0)},
  "tipo_pago": {"valor": (string), "confianza": (0.0-1.0)},
  "referencia": {"valor": (código alfanumérico o null), "confianza": (0.0-1.0)},
  "fecha": {"valor": ("YYYY-MM-DD" o null), "confianza": (0.0-1.0)},
  "hora": {"valor": ("HH:MM:SS" o null), "confianza": (0.0-1.0)},
  "banco_billetera": {"valor": (nombre normalizado del banco/billetera DESTINO o null), "confianza": (0.0-1.0)},
  "banco_origen": {"valor": (nombre del banco/billetera ORIGEN o null), "confianza": (0.0-1.0)},
  "cuenta_destino": {"valor": (cadena con caracteres visibles o null), "confianza": (0.0-1.0)},
  "cuenta_origen": {"valor": (cadena con caracteres visibles o null), "confianza": (0.0-1.0)},
  "nombre_depositante": {"valor": (nombre del pagador o null), "confianza": (0.0-1.0)},
  "nombre_beneficiario": {"valor": (nombre del receptor o null), "confianza": (0.0-1.0)},
  "agencia": {"valor": (agencia o sucursal o null), "confianza": (0.0-1.0)},
  "legible": (true si monto.confianza >= 0.7 Y referencia.confianza >= 0.7, false en caso contrario)
}`;

// Orden fijo de los campos en el prompt
const ORDEN_CAMPOS = [
  "GENERAL","BANCO_BILLETERA","BANCO_ORIGEN","CUENTA_DESTINO","CUENTA_ORIGEN",
  "REFERENCIA","NOMBRE_BENEFICIARIO","NOMBRE_DEPOSITANTE","TIPO_PAGO",
  "MONTO","FECHA","HORA","AGENCIA"
];

// Etiqueta legible por campo (para el encabezado del bloque)
const ETIQUETA = {
  GENERAL:"GENERAL", BANCO_BILLETERA:"BANCO_BILLETERA", BANCO_ORIGEN:"BANCO_ORIGEN",
  CUENTA_DESTINO:"CUENTA_DESTINO", CUENTA_ORIGEN:"CUENTA_ORIGEN", REFERENCIA:"REFERENCIA",
  NOMBRE_BENEFICIARIO:"NOMBRE_BENEFICIARIO", NOMBRE_DEPOSITANTE:"NOMBRE_DEPOSITANTE",
  TIPO_PAGO:"TIPO_PAGO", MONTO:"MONTO", FECHA:"FECHA", HORA:"HORA", AGENCIA:"AGENCIA"
};

// 1. Tomar todas las filas del Sheet (este nodo recibe las filas de "Leer reglas prompt")
const filas = $input.all().map(i => i.json);

// 2. Filtrar solo activas con texto de regla
const reglas = filas.filter(r =>
  r && String(r.activo).trim().toUpperCase() === "TRUE" &&
  r.regla && String(r.regla).trim() !== ""
);

// 3. Agrupar por campo
const porCampo = {};
for (const r of reglas) {
  const campo = String(r.campo || "GENERAL").trim().toUpperCase();
  (porCampo[campo] = porCampo[campo] || []).push(r);
}
// 4. Ordenar cada grupo por 'orden'
for (const k in porCampo) {
  porCampo[k].sort((a,b) => Number(a.orden || 0) - Number(b.orden || 0));
}

// 5. Construir ZONA B respetando ORDEN_CAMPOS; campos no listados van al final
const camposPresentes = Object.keys(porCampo);
const extras = camposPresentes.filter(c => !ORDEN_CAMPOS.includes(c));
const secuencia = [...ORDEN_CAMPOS, ...extras];

let zonaB = "";
for (const campo of secuencia) {
  if (!porCampo[campo] || !porCampo[campo].length) continue;
  zonaB += "\n\n[" + (ETIQUETA[campo] || campo) + "]\n";
  zonaB += porCampo[campo].map(r => "- " + String(r.regla).trim()).join("\n");
}

// 6. Recuperar imagen desde CONVERTIR A BASE64 (no se pierde aunque leímos el Sheet)
let conv;
try {
  conv = $('CONVERTIR A BASE64').item.json;
} catch (e) {
  conv = {};
}

// 7. Fallback defensivo: si no hay reglas activas, NO mandar a Groq sin instrucciones
if (!zonaB.trim()) {
  return [{
    json: {
      ...conv,
      error: true,
      legible: false,
      motivo_error: "No hay reglas de prompt activas en la hoja prompt_comprobante"
    }
  }];
}

const promptComprobante = ZONA_A + zonaB + "\n\n" + ZONA_C;

return [{
  json: {
    ...conv,                       // arrastra imageBase64, imageMimeType, phone, guia, transportista, etc.
    promptComprobante: promptComprobante,
    reglas_activas: reglas.length
  }
}];

