// ADMIN TODAS -> 3 items (uno por maestro). Caso normal -> 1 item.
// 'Leer Liquidaciones (informe)' usa $json.maestro_id como documentId.
let maestros = null;
try { maestros = $('Sufijo reporte INF').first().json.maestros; } catch (e) {}
if (!Array.isArray(maestros) || maestros.length === 0) {
  const a = $('Resolver Sucursal').first().json;
  const maestroDe = c => (String(c).toUpperCase() === 'COM')
    ? $vars.SHEET_ID_MAESTRO
    : ($vars['MAESTRO_' + String(c).toUpperCase()] || $vars.SHEET_ID_MAESTRO);
  const cod = String(a.sucursal_codigo || 'COM').toUpperCase();
  maestros = [{ codigo: cod, nombre: a.sucursal_nombre || cod, id: a.maestro_id || maestroDe(cod) }];
}
return maestros.map(m => ({ json: { maestro_codigo: m.codigo, maestro_nombre: m.nombre, maestro_id: m.id } }));
